 1→import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
 2→import { Outlet, useLoaderData, useNavigation, useRouteError } from "react-router";
 3→import { boundary } from "@shopify/shopify-app-react-router/server";
 4→import { AppProvider } from "@shopify/shopify-app-react-router/react";
 5→import {
 6→  AppProvider as PolarisAppProvider,
 7→  SkeletonPage,
 8→  Layout,
 9→  Card,
10→  SkeletonBodyText,
11→  SkeletonDisplayText,
12→} from "@shopify/polaris";
13→import "@shopify/polaris/build/esm/styles.css";
14→import enTranslations from "@shopify/polaris/locales/en.json";
15→
16→import { authenticate } from "../shopify.server";
17→
18→export const loader = async ({ request }: LoaderFunctionArgs) => {
19→  await authenticate.admin(request);
20→
21→  // eslint-disable-next-line no-undef
22→  return { apiKey: process.env.SHOPIFY_API_KEY || "" };
23→};
24→
25→function AppContent() {
26→  const navigation = useNavigation();
27→  const isNavigating = navigation.state === "loading";
28→
29→  if (isNavigating) {
30→    return (
31→      <SkeletonPage primaryAction>
32→        <Layout>
33→          <Layout.Section>
34→            <Card>
35→              <SkeletonDisplayText size="small" />
36→              <SkeletonBodyText lines={3} />
37→            </Card>
38→          </Layout.Section>
39→          <Layout.Section>
40→            <Card>
41→              <SkeletonBodyText lines={6} />
42→            </Card>
43→          </Layout.Section>
44→        </Layout>
45→      </SkeletonPage>
46→    );
47→  }
48→
49→  return <Outlet />;
50→}
51→
52→export default function App() {
53→  const { apiKey } = useLoaderData<typeof loader>();
54→
55→  return (
56→    <AppProvider embedded apiKey={apiKey}>
57→      <PolarisAppProvider i18n={enTranslations}>
58→        <s-app-nav>
59→          <s-link href="/app">Dashboard</s-link>
60→          <s-link href="/app/size-charts">Size Charts</s-link>
61→          <s-link href="/app/recommender">AI Recommender</s-link>
62→          <s-link href="/app/widget">Widget</s-link>
63→          <s-link href="/app/analytics">Analytics</s-link>
64→          <s-link href="/app/pricing">Pricing</s-link>
65→          <s-link href="/app/settings">Settings</s-link>
66→        </s-app-nav>
67→        <AppContent />
68→      </PolarisAppProvider>
69→    </AppProvider>
