73→// Shopify needs React Router to catch some thrown responses, so that their headers are included in the response.
74→export function ErrorBoundary() {
75→  return boundary.error(useRouteError());
76→}
77→
78→export const headers: HeadersFunction = (headersArgs) => {
79→  return boundary.headers(headersArgs);
80→};
