  1→import { useEffect, useState } from "react";
  2→import type { LoaderFunctionArgs, ActionFunctionArgs } from "react-router";
  3→import { useLoaderData, useFetcher, useNavigate } from "react-router";
  4→import { useAppBridge } from "@shopify/app-bridge-react";
  5→import {
  6→  Page,
  7→  Layout,
  8→  Card,
  9→  BlockStack,
 10→  InlineStack,
 11→  Text,
 12→  Badge,
 13→  Button,
 14→  ButtonGroup,
 15→  Banner,
 16→  Divider,
 17→  InlineGrid,
 18→  Modal,
 19→  TextField,
 20→  Select,
 21→  Icon,
 22→} from "@shopify/polaris";
 23→import { SearchIcon } from "@shopify/polaris-icons";
 24→import { authenticate } from "../shopify.server";
 25→import db from "../db.server";
 26→import { getPlan, canCreateChart } from "../lib/plans";
 27→import { SIZE_CHART_TEMPLATES, getCategories } from "../lib/templates";
 28→
 29→export const loader = async ({ request }: LoaderFunctionArgs) => {
 30→  const { session } = await authenticate.admin(request);
 31→  const shop = session.shop;
 32→
 33→  const [charts, subscription] = await Promise.all([
 34→    db.sizeChart.findMany({
 35→      where: { shop },
 36→      orderBy: { updatedAt: "desc" },
 37→      include: { assignments: true },
 38→    }),
 39→    db.subscription.findUnique({ where: { shop } }),
 40→  ]);
 41→
 42→  const plan = getPlan(subscription?.planId ?? "free");
 43→  const templates = SIZE_CHART_TEMPLATES.map((t) => ({
 44→    name: t.name,
 45→    category: t.category,
 46→    gender: t.gender,
 47→    rowCount: t.data.rows.length,
 48→  }));
 49→  const categories = getCategories();
 50→
 51→  return {
 52→    charts,
 53→    plan,
 54→    templates,
 55→    categories,
 56→    canCreate: canCreateChart(plan.id, charts.length),
 57→  };
 58→};
 59→
 60→export const action = async ({ request }: ActionFunctionArgs) => {
 61→  const { session } = await authenticate.admin(request);
 62→  const shop = session.shop;
 63→  const formData = await request.formData();
 64→  const intent = formData.get("intent") as string;
 65→
 66→  try {
 67→    switch (intent) {
 68→      case "create-from-template": {
 69→        const templateName = formData.get("templateName") as string;
 70→        const template = SIZE_CHART_TEMPLATES.find((t) => t.name === templateName);
 71→        if (!template) return { error: "Template not found" };
 72→
 73→        const subscription = await db.subscription.findUnique({ where: { shop } });
 74→        const plan = getPlan(subscription?.planId ?? "free");
 75→        const chartCount = await db.sizeChart.count({ where: { shop } });
 76→        if (!canCreateChart(plan.id, chartCount)) {
 77→          return {
 78→            error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.`,
 79→          };
 80→        }
 81→
 82→        let name = template.name;
 83→        const existing = await db.sizeChart.findUnique({
 84→          where: { shop_name: { shop, name } },
 85→        });
 86→        if (existing) name = `${template.name} (${Date.now().toString(36)})`;
 87→
 88→        const created = await db.sizeChart.create({
 89→          data: {
 90→            shop,
 91→            name,
 92→            category: template.category,
 93→            data: JSON.stringify(template.data),
 94→            status: "active",
 95→          },
 96→        });
 97→        return { ok: true, message: `"${name}" created successfully`, redirectId: created.id };
 98→      }
 99→
100→      case "create-blank": {
101→        const name = (formData.get("name") as string) || "Untitled Size Chart";
102→        const category = (formData.get("category") as string) || "general";
103→
104→        const subscription = await db.subscription.findUnique({ where: { shop } });
105→        const plan = getPlan(subscription?.planId ?? "free");
106→        const chartCount = await db.sizeChart.count({ where: { shop } });
107→        if (!canCreateChart(plan.id, chartCount)) {
108→          return {
109→            error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.`,
110→          };
111→        }
112→
113→        let uniqueName = name;
114→        const existing = await db.sizeChart.findUnique({
115→          where: { shop_name: { shop, name } },
116→        });
117→        if (existing) uniqueName = `${name} (${Date.now().toString(36)})`;
118→
119→        const defaultData = {
120→          headers: ["Size", "Chest", "Waist", "Hips"],
121→          units: { default: "in", available: ["in", "cm"] },
122→          rows: [
123→            { Size: "S", Chest: "", Waist: "", Hips: "" },
124→            { Size: "M", Chest: "", Waist: "", Hips: "" },
125→            { Size: "L", Chest: "", Waist: "", Hips: "" },
126→          ],
127→        };
128→
129→        const created = await db.sizeChart.create({
130→          data: {
131→            shop,
132→            name: uniqueName,
133→            category,
134→            data: JSON.stringify(defaultData),
135→            status: "draft",
136→          },
137→        });
138→        return { ok: true, message: `"${uniqueName}" created`, redirectId: created.id };
139→      }
140→
141→      case "delete": {
142→        const id = formData.get("id") as string;
143→        await db.sizeChart.deleteMany({ where: { id, shop } });
144→        return { ok: true, message: "Chart deleted" };
145→      }
146→
147→      case "import-csv": {
148→        const csvRaw = formData.get("csvData") as string;
149→        const chartName = (formData.get("name") as string) || "Imported Size Chart";
150→        const category = (formData.get("category") as string) || "general";
151→
152→        if (!csvRaw?.trim()) return { error: "CSV data is required" };
153→
154→        const subscription = await db.subscription.findUnique({ where: { shop } });
155→        const plan = getPlan(subscription?.planId ?? "free");
156→        const chartCount = await db.sizeChart.count({ where: { shop } });
157→        if (!canCreateChart(plan.id, chartCount)) {
158→          return { error: `Free plan allows max ${plan.limits.maxCharts} charts. Upgrade to create more.` };
159→        }
160→
161→        // Parse CSV
162→        const lines = csvRaw.trim().split(/\r?\n/).filter((l) => l.trim());
163→        if (lines.length < 2) return { error: "CSV must have a header row and at least one data row." };
164→
165→        const parseRow = (line: string): string[] => {
166→          const result: string[] = [];
167→          let current = "";
168→          let inQuotes = false;
169→          for (let i = 0; i < line.length; i++) {
170→            const ch = line[i];
171→            if (ch === '"') {
172→              if (inQuotes && line[i + 1] === '"') { current += '"'; i++; }
173→              else { inQuotes = !inQuotes; }
174→            } else if (ch === "," && !inQuotes) {
175→              result.push(current.trim());
176→              current = "";
177→            } else {
178→              current += ch;
179→            }
180→          }
181→          result.push(current.trim());
182→          return result;
183→        };
184→
185→        const headers = parseRow(lines[0]);
186→        if (headers.length < 1) return { error: "Could not parse CSV headers." };
187→
188→        const rows = lines.slice(1).map((line) => {
189→          const cells = parseRow(line);
190→          const row: Record<string, string> = {};
191→          headers.forEach((h, i) => { row[h] = cells[i] ?? ""; });
192→          return row;
193→        });
194→
195→        const data = {
196→          headers,
197→          units: { default: "in", available: ["in", "cm"] },
198→          rows,
199→        };
200→
201→        let uniqueName = chartName;
202→        const existingName = await db.sizeChart.findUnique({ where: { shop_name: { shop, name: chartName } } });
203→        if (existingName) uniqueName = `${chartName} (${Date.now().toString(36)})`;
204→
205→        const created = await db.sizeChart.create({
206→          data: { shop, name: uniqueName, category, data: JSON.stringify(data), status: "draft" },
207→        });
208→        return { ok: true, message: `Imported "${uniqueName}"`, redirectId: created.id };
209→      }
210→
211→      case "duplicate": {
212→        const sourceId = formData.get("id") as string;
213→        const source = await db.sizeChart.findFirst({ where: { id: sourceId, shop } });
214→        if (!source) return { error: "Chart not found" };
215→
216→        const subscription = await db.subscription.findUnique({ where: { shop } });
217→        const plan = getPlan(subscription?.planId ?? "free");
218→        const chartCount = await db.sizeChart.count({ where: { shop } });
219→        if (!canCreateChart(plan.id, chartCount)) {
220→          return { error: "Chart limit reached. Upgrade your plan." };
221→        }
222→
223→        const newName = `${source.name} (Copy)`;
224→        await db.sizeChart.create({
225→          data: {
226→            shop,
227→            name: newName,
228→            type: source.type,
229→            category: source.category,
230→            data: source.data,
231→            status: "draft",
232→          },
233→        });
234→        return { ok: true, message: `Duplicated as "${newName}"` };
235→      }
236→
237→      case "toggle-status": {
238→        const chartId = formData.get("id") as string;
239→        const chart = await db.sizeChart.findFirst({ where: { id: chartId, shop } });
240→        if (!chart) return { error: "Chart not found" };
241→
242→        const newStatus = chart.status === "active" ? "draft" : "active";
243→        await db.sizeChart.update({ where: { id: chartId }, data: { status: newStatus } });
244→        return {
245→          ok: true,
246→          message: `Chart ${newStatus === "active" ? "published" : "unpublished"}`,
247→        };
248→      }
249→
250→      default:
251→        return { error: "Unknown action" };
252→    }
253→  } catch (error) {
254→    const message = error instanceof Error ? error.message : "An unexpected error occurred";
255→    if (message.includes("Unique constraint")) {
256→      return { error: "A chart with this name already exists." };
257→    }
258→    return { error: message };
259→  }
260→};
