262→// ---------------------------------------------------------------------------
263→// Types
264→// ---------------------------------------------------------------------------
265→
266→type ActionData =
267→  | { ok: true; message: string; redirectId?: string }
268→  | { error: string };
269→
270→// ---------------------------------------------------------------------------
271→// Constants
272→// ---------------------------------------------------------------------------
273→
274→const CATEGORY_LABELS: Record<string, string> = {
275→  tops: "Tops",
276→  bottoms: "Bottoms",
277→  dresses: "Dresses",
278→  shoes: "Shoes",
279→  kids: "Kids",
280→  rings: "Rings",
281→  sportswear: "Sportswear",
282→  general: "General",
283→};
284→
285→const CATEGORY_ICONS: Record<string, string> = {
286→  tops: "👕",
287→  bottoms: "👖",
288→  dresses: "👗",
289→  shoes: "👟",
290→  kids: "🧒",
291→  rings: "💍",
292→  sportswear: "🏃",
293→  general: "📏",
294→};
295→
296→const CATEGORY_SELECT_OPTIONS = [
297→  { label: "General", value: "general" },
298→  { label: "Tops", value: "tops" },
299→  { label: "Bottoms", value: "bottoms" },
300→  { label: "Dresses", value: "dresses" },
301→  { label: "Shoes", value: "shoes" },
302→  { label: "Kids", value: "kids" },
303→  { label: "Rings", value: "rings" },
304→  { label: "Sportswear", value: "sportswear" },
305→];
