178→// ---------------------------------------------------------------------------
179→// Helpers
180→// ---------------------------------------------------------------------------
181→
182→function parseChartData(raw: string): ChartData {
183→  try {
184→    const parsed = JSON.parse(raw) as unknown;
185→    if (
186→      parsed !== null &&
187→      typeof parsed === "object" &&
188→      !Array.isArray(parsed)
189→    ) {
190→      const obj = parsed as Record<string, unknown>;
191→      return {
192→        headers: Array.isArray(obj.headers) ? (obj.headers as string[]) : [],
193→        units:
194→          obj.units !== null &&
195→          typeof obj.units === "object" &&
196→          !Array.isArray(obj.units)
197→            ? (obj.units as { default: string; available: string[] })
198→            : { default: "in", available: ["in", "cm"] },
199→        rows: Array.isArray(obj.rows)
200→          ? (obj.rows as Record<string, string>[])
201→          : [],
202→      };
203→    }
204→  } catch {
205→    // fall through to default
206→  }
207→  return {
208→    headers: [],
209→    units: { default: "in", available: ["in", "cm"] },
210→    rows: [],
211→  };
212→}
